-- Yung Network: schema + migrazione sicura per news, staff e social
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.news (id bigint generated by default as identity primary key,title text not null check (char_length(title) between 1 and 120),summary text not null default '',content text not null default '',category text not null default 'Community',image_url text,status text not null default 'draft' check (status in ('draft','published')),published_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.news add column if not exists expires_at timestamptz;
create table if not exists public.staff_members (id bigint generated by default as identity primary key,name text not null,role text not null default 'Staff',bio text not null default '',initials text not null default '',avatar_url text,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.social_links (id bigint generated by default as identity primary key,label text not null,url text not null,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
alter table public.admin_users enable row level security; alter table public.news enable row level security; alter table public.staff_members enable row level security; alter table public.social_links enable row level security;
drop policy if exists "Admins can read own admin record" on public.admin_users; create policy "Admins can read own admin record" on public.admin_users for select to authenticated using (user_id = auth.uid());
drop policy if exists "Anyone can read published news" on public.news; create policy "Anyone can read published news" on public.news for select to anon, authenticated using ((status = 'published' and (expires_at is null or expires_at > now())) or exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
drop policy if exists "Admins can insert news" on public.news; create policy "Admins can insert news" on public.news for insert to authenticated with check (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
drop policy if exists "Admins can update news" on public.news; create policy "Admins can update news" on public.news for update to authenticated using (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid())) with check (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
drop policy if exists "Admins can delete news" on public.news; create policy "Admins can delete news" on public.news for delete to authenticated using (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
drop policy if exists "Public can read active staff" on public.staff_members; create policy "Public can read active staff" on public.staff_members for select to anon, authenticated using (active or exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
drop policy if exists "Admins manage staff" on public.staff_members; create policy "Admins manage staff" on public.staff_members for all to authenticated using (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid())) with check (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
drop policy if exists "Public can read active socials" on public.social_links; create policy "Public can read active socials" on public.social_links for select to anon, authenticated using (active or exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
drop policy if exists "Admins manage socials" on public.social_links; create policy "Admins manage socials" on public.social_links for all to authenticated using (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid())) with check (exists (select 1 from public.admin_users where admin_users.user_id = auth.uid()));
grant select on public.news,public.staff_members,public.social_links to anon,authenticated; grant insert,update,delete on public.news,public.staff_members,public.social_links to authenticated; grant select on public.admin_users to authenticated;
